mapper.select:
SELECT e.*, s.name as student_name, c.class_name, co.college_name, m.major_name
FROM student_employment e
LEFT JOIN student s ON e.student_id = s.student_no
LEFT JOIN class c ON s.class_code = c.class_code
LEFT JOIN college co ON c.college_code = co.college_code
LEFT JOIN major m ON s.major_code = m.major_code


        AND e.student_id = #{studentId}


        AND e.graduation_year = #{graduationYear}


        AND e.employment_status = #{employmentStatus}


        AND co.college_code = #{collegeCode}


ORDER BY e.record_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM student_employment e
LEFT JOIN student s ON e.student_id = s.student_no
LEFT JOIN class c ON s.class_code = c.class_code
LEFT JOIN college co ON c.college_code = co.college_code


        AND e.student_id = #{studentId}


        AND e.graduation_year = #{graduationYear}


        AND e.employment_status = #{employmentStatus}


        AND co.college_code = #{collegeCode}

SELECT e.graduation_year as year, e.employment_status as status, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM student_employment WHERE graduation_year = #{graduationYear}), 2) as percentage FROM student_employment e LEFT JOIN student s ON e.student_id = s.student_no LEFT JOIN class c ON s.class_code = c.class_code
AND e.graduation_year = #{graduationYear}
AND c.college_code = #{collegeCode}
GROUP BY e.graduation_year, e.employment_status ORDER BY e.graduation_year DESC

SELECT e.industry as industry, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM student_employment WHERE employment_status = 'EMPLOYED'), 2) as percentage FROM student_employment e LEFT JOIN student s ON e.student_id = s.student_no LEFT JOIN class c ON s.class_code = c.class_code
e.employment_status = 'EMPLOYED'
AND e.graduation_year = #{graduationYear}
AND c.college_code = #{collegeCode}
GROUP BY e.industry ORDER BY count DESC

SELECT e.company_type as companyType, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM student_employment WHERE employment_status = 'EMPLOYED'), 2) as percentage FROM student_employment e LEFT JOIN student s ON e.student_id = s.student_no LEFT JOIN class c ON s.class_code = c.class_code
e.employment_status = 'EMPLOYED'
AND e.graduation_year = #{graduationYear}
AND c.college_code = #{collegeCode}
GROUP BY e.company_type ORDER BY count DESC

SELECT
    (SELECT COUNT(*) FROM student_employment WHERE employment_status IN ('EMPLOYED', 'SELF_EMPLOYED')

            AND graduation_year = #{graduationYear}

    ) as employedCount,
    (SELECT COUNT(DISTINCT student_id) FROM student


                SUBSTRING(student_no, 1, 4) = #{graduationYear}


                AND class_code IN (SELECT class_code FROM class WHERE college_code = #{collegeCode})


    ) as totalCount,
    ROUND(
        (SELECT COUNT(*) FROM student_employment WHERE employment_status IN ('EMPLOYED', 'SELF_EMPLOYED')

                AND graduation_year = #{graduationYear}

        ) * 100.0 /
        (SELECT COUNT(DISTINCT student_id) FROM student


                    SUBSTRING(student_no, 1, 4) = #{graduationYear}


                    AND class_code IN (SELECT class_code FROM class WHERE college_code = #{collegeCode})


        ), 2
    ) as employmentRate
